package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: {@code ZFSD_PRICE_SIMULATION} 
 */
public class PricingCallDTO implements Serializable {

	private static final long serialVersionUID = -1739422914527802038L;

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / CALLER
	 */
	private String caller = "LOGON";

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZSSD_PS_HEADER
	 */
	private PricingCallDTOHeader header;

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_PARTNERS
	 */
	private PricingCallDTOPartners partners;

	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS 
	 */
	private PricingCallDTOItems items;

	public String getCaller() {
		return caller;
	}

	public void setCaller(String caller) {
		this.caller = caller;
	}

	public PricingCallDTOHeader getHeader() {
		return header;
	}

	public void setHeader(PricingCallDTOHeader header) {
		this.header = header;
	}

	public PricingCallDTOPartners getPartners() {
		return partners;
	}

	public void setPartners(PricingCallDTOPartners partners) {
		this.partners = partners;
	}

	public PricingCallDTOItems getItems() {
		return items;
	}

	public void setItems(PricingCallDTOItems items) {
		this.items = items;
	}

	@Override
	public String toString() {
		return "PricingCallDTO [caller=" + caller + ", header=" + header + ", partners=" + partners
				+ ", items=" + items + "]";
	}

}